 void restore(SharedPreferences p,Map<String,?> data){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> pair:data.entrySet()){Object v=pair.getValue();if(v instanceof String)e.putString(pair.getKey(),(String)v);else if(v instanceof Boolean)e.putBoolean(pair.getKey(),(Boolean)v);else if(v instanceof Long)e.putLong(pair.getKey(),(Long)v);else if(v instanceof Integer)e.putInt(pair.getKey(),(Integer)v);else if(v instanceof Float)e.putFloat(pair.getKey(),(Float)v);else if(v instanceof Set)e.putStringSet(pair.getKey(),(Set<String>)v);}e.commit();}
